<template><AppShell title="兑换记录" back><StateView :loading="loading" :error="error" :count="order?1:0" @retry="load" /><view class="pad" v-if="order"><view class="card"><text class="tag">{{rewardStatus[order.status]}}</text><text class="title">{{order.title}}</text><text class="muted tiny">兑换编号 {{order.id}} · {{date(order.createdAt)}}</text><text class="description" v-if="order.kind==='BADGE'">勋章已添加到个人主页。</text><button v-if="order.kind==='BADGE'" class="ui-button btn section" @click="go('shop/index',{id:session.user.id})">查看我的勋章</button></view><view class="card section" v-if="['WAIT_ADDRESS','WAIT_SHIP'].includes(order.status)"><text class="bold">收货信息</text><text class="muted tiny description">仅用于寄送兑换实物，发货后不能修改。</text><view class="address-field"><text>收货人</text><input v-model="form.recipient" maxlength="50" placeholder="请输入收货人" /></view><view class="address-field"><text>手机号</text><input v-model="form.phone" type="number" maxlength="11" placeholder="大陆手机号" /></view><view class="address-field"><text>详细地址</text><textarea v-model="form.address" maxlength="300" placeholder="省、市、区和街道门牌" /></view><button class="ui-button btn" :disabled="busy" @click="save">{{busy?'保存中…':'保存收货信息'}}</button></view><view class="card section" v-if="order.recipient"><text class="bold">收货地址</text><text class="description">{{order.recipient}} · {{order.phone}}<br/>{{order.address}}</text></view><view class="card section" v-if="order.carrier"><text class="bold">物流信息</text><text class="description">{{order.carrier}}<br/>{{order.trackingNo}}</text><button class="ui-button btn outline section" @click="copy">复制物流单号</button></view><button v-if="order.status==='SHIPPED'" class="ui-button btn section" :disabled="busy" @click="receive">确认收货</button></view></AppShell><ConfirmAction v-if="confirmation.open" :key="confirmation.id" :state="confirmation" @answer="answerConfirmation" /></template>
<script setup>
import ConfirmAction from '../../components/ConfirmAction.vue';import {useConfirmation} from '../../lib/confirmation'
const {confirmation,confirm,answerConfirmation}=useConfirmation()
import {ref,reactive,watch} from 'vue';import {onLoad,onShow,onUnload} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import StateView from '../../components/StateView.vue';import {request,requireLogin,session,go,date,toast,loadMe} from '../../lib/api';import {rewardStatus} from '../../lib/rewards'
const id=ref(''),order=ref(null),form=reactive({recipient:'',phone:'',address:''}),loading=ref(false),error=ref(''),busy=ref(false);let generation=0;onLoad(q=>id.value=q.id);onShow(async()=>{if(requireLogin()){try{if(!session.user)await loadMe();load()}catch(e){error.value=e.message}}});onUnload(resetPrivate);watch(()=>session.token,resetPrivate,{flush:'sync'})
function resetPrivate(){generation++;order.value=null;Object.assign(form,{recipient:'',phone:'',address:''});busy.value=false;loading.value=false;error.value=''}
async function load(){const v=++generation;order.value=null;Object.assign(form,{recipient:'',phone:'',address:''});loading.value=true;error.value='';try{const r=await request('/boost/rewards/orders/'+id.value);if(v===generation){order.value=r;Object.assign(form,{recipient:r.recipient,phone:r.phone,address:r.address})}}catch(e){if(v===generation)error.value=e.message}finally{if(v===generation)loading.value=false}}
async function save(){if(busy.value)return;busy.value=true;const v=generation;try{const r=await request(`/boost/rewards/orders/${id.value}/address`,'PUT',{...form});if(v===generation){order.value=r;toast('收货信息已保存')}}catch(e){toast(e.message)}finally{if(v===generation)busy.value=false}}
async function receive(){if(busy.value)return;busy.value=true;const v=generation,token=session.token;try{if(!await confirm('请确认实物已经收到，再确认收货。'))return;if(v!==generation||token!==session.token)return;const r=await request(`/boost/rewards/orders/${id.value}/receive`,'POST');if(v===generation){order.value=r;toast('已确认收货')}}catch(e){toast(e.message)}finally{if(v===generation)busy.value=false}}
function copy(){uni.setClipboardData({data:order.value.trackingNo})}
</script>
<style scoped>.title{display:block;font-weight:750;font-size:23px;margin:14px 0}.description{display:block;line-height:1.8;font-size:13px;margin-top:12px;overflow-wrap:anywhere;white-space:pre-wrap}.address-field{border-bottom:1px solid #ececf0;padding:15px 0;font-size:13px}.address-field input{height:36px}.address-field textarea{width:100%;height:80px;margin-top:10px}.address-field>text{color:#70737a}.card .btn{margin-top:16px}</style>
